    # false — this ingest carried no key for them, so the argv-prose seam would have refused with an
    # escape that did not exist. FOUR KEYS IN THIS EXISTING TABLE, not four new per-verb routes.
    ("settle_reason",              "--settle-reason",              "settle_reason",              None),
    ("asserts",                    "--asserts",                    "asserts",                    None),
