def _resolves_cross_link_error(tid, value, current, items, self_name, tasks_dir):
    """T-13339: validate a `--set-field resolves_cross` value. PURE but for the read-only tasks-dir
    scan. Returns (normalized, added, None) or (None, None, reason) — every reason leads with a NAMED
    code. ADD-ONLY: the value must keep every link the card already carries. Each ADDED id must exist
    in the shared-log fold, be addressed TO this project, and not be linked by a different LIVE
    (non-done / non-wont-do) card."""
    if not isinstance(value, list) or not value:
        return None, None, ("needs a non-empty YAML LIST of X-NNNN ids "
                            f"(got {type(value).__name__})")
    norm: list = []
    for v in value:
        v = str(v).strip()
        if not CROSS_ID_RE.match(v):
            return None, None, f"bad-cross-id: entries must be X-NNNN coordination ids; got {v!r}"
        if v not in norm:
            norm.append(v)
    cur = [str(x).strip() for x in (current if isinstance(current, list) else [current] if current else [])]
    dropped = [x for x in cur if x not in norm]
    if dropped:
        return None, None, (f"link-removal-not-supported: the value drops {', '.join(dropped)} — this "
                            f"route only ADDS links; keep the existing ones in the list")
    added = [x for x in norm if x not in cur]
    for xid in added:
        item = (items or {}).get(xid)
        if not isinstance(item, dict):
            return None, None, f"unknown-cross-id: {xid} is not on the shared coordination log"
        if item.get("to") != self_name:
            return None, None, (f"addressed-to-other-project: {xid} is addressed to "
                                f"{item.get('to')!r}, not this project ({self_name!r})")
        for p in sorted(Path(tasks_dir).glob("T-*.yaml")):
            try:
                t = state.load_path(p)
            except Exception:                          # noqa: BLE001 — an unreadable card links nothing
                continue
            if not isinstance(t, dict) or t.get("id") == tid or t.get("status") in ("done", "wont-do"):
                continue
            rc = t.get("resolves_cross") or []
            if xid in (rc if isinstance(rc, list) else [rc]):
                return None, None, (f"already-linked: {xid} is already linked to live card "
                                    f"{t.get('id')} ({t.get('status')})")
    return norm, added, None


def _probe_moments_value_error(value, acceptance):
    """T-13247: validate a `--set-field probe_moments` value. PURE. Returns (normalized, None) or
    (None, reason). FAIL-CLOSED on the SAME two conditions the reader (`audit.declared_deferred_probe_rows`)
    admits by — so nothing this writer stores is silently dropped at audit-pre:
      (i)  GRAMMAR — each entry is a mapping with EXACTLY one of `awaits` / `due_by`, whose moment
           parses under `_probe_moment_declaration` (the single parse home);
      (ii) NAMESPACE — each key leads with a criterion id THIS card's acceptance names.
    Normalized keys are the canonical `<PREFIX><n>` label; values the parser's stored shape."""
    if not isinstance(value, dict) or not value:
        return None, (f"needs a non-empty YAML MAPPING like `{{AC2: {{awaits: T-1234}}}}` "
                      f"(got {type(value).__name__})")
    legal_ids, _ = _criterion_key_namespace(acceptance)
    if not legal_ids:
        return None, "the card's acceptance names no criterion ids (ACn:), so there is nothing to defer"
    out = {}
    for key, entry in value.items():
        cid = _leading_criterion_id(key)
        if cid is None or cid not in legal_ids:
            _legal = ", ".join(f"{p}{n}" for p, n in sorted(legal_ids))
            return None, f"key {key!r} names no criterion of this card (legal: {_legal})"
        label = f"{cid[0]}{cid[1]}"
        if label in out:
            return None, f"criterion {label} is declared twice"
        slots = [k for k in ("awaits", "due_by") if isinstance(entry, dict) and k in entry]
        if not isinstance(entry, dict) or len(slots) != 1 or len(entry) != 1:
            return None, (f"{label} must be a mapping with EXACTLY one of `awaits` / `due_by` "
                          f"(got {entry!r})")
        decl = _probe_moment_declaration(entry[slots[0]])
        if decl is None or slots[0] not in decl:
            # Not `_probe_moment_refusal`: that wording names the CLOSE-time door (`--probe-deferred`).
            return None, (f"{label}: {entry[slots[0]]!r} is not a `{slots[0]}` moment any reader can "
                          f"decide — use `due_by: <ISO date>`, or `awaits:` a task/cross id (T-1234 / "
                          f"X-0042) or `events.jsonl#type=<t>[@after=<ISO ts>|@after=land]`")
        out[label] = decl
    return out, None


def _answers_error(value):
    """T-13221: why an `answers:` value (SPEC-0197 rule 4 link-back) cannot be written, else None.

    The SAME two checks `release.collect_answered_proposals` fails closed on at publish — the id
    grammar `ANSWER_ID_RE` and no host absolute path — applied at the WRITE doors, so a bad id is
    refused when it is authored rather than when a release is cut. Pure; the regexes stay homed in
    release.py (imported lazily, release.py never imports this module)."""
    from lib import release
    if not (isinstance(value, list) and value):
        return "needs a non-empty YAML LIST of proposal ids (e.g. ['#8'])"
    for item in value:
        aid = str(item).strip() if isinstance(item, (str, int)) else None
        if not aid or not release.ANSWER_ID_RE.match(aid):
            return (f"id {item!r} fails the link-back id grammar (release.ANSWER_ID_RE: one line, "
                    f"<=64 chars, e.g. '#8')")
        if release.HOST_PATH_RE.search(aid):
            return f"id {item!r} contains a host absolute path — a release is host-clean"
    return None
