    kw = {**{"_audit_scrutiny_cases": _audit_scrutiny_cases, "_case_attributions": _case_attributions,
            "_case_closure_index": _case_closure_index,
            "_case_revision_proposal": _case_revision_proposal,
            "_followup_overlap_events_path": _followup_overlap_events_path}, **kw}
